#include <vector>
#include <climits>
#include <algorithm>

using namespace std;

class Solution {
public:
    vector<int> minCosts(vector<int>& cost) {
        vector<int> ans;
        ans.reserve(cost.size());
        int curMin = INT_MAX;
        for (int x : cost) {
            curMin = min(curMin, x);
            ans.push_back(curMin);
        }
        return ans;
    }
};

class Solution {
    public int[] minCosts(int[] cost) {
        int n = cost.length;
        int[] ans = new int[n];
        int curMin = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            curMin = Math.min(curMin, cost[i]);
            ans[i] = curMin;
        }
        return ans;
    }
}

